g5(name) AS (VALUES ('20261109090000_accountant_delivery_permission'), ('20261109091000_accountant_link_otp')),
led AS (SELECT migration_name AS name, checksum, finished_at IS NOT NULL AND rolled_back_at IS NULL AS ok FROM "_prisma_migrations"),
notrun AS (SELECT r.name FROM repo r WHERE NOT EXISTS (SELECT 1 FROM led l WHERE l.name = r.name AND l.ok)),
leads AS (SELECT EXISTS (SELECT 1 FROM led WHERE name = '20261108090000_lead_claimed_phone' AND ok) AS done),
expect AS (SELECT name FROM g5 UNION ALL SELECT '20261108090000_lead_claimed_phone' WHERE NOT (SELECT done FROM leads)),
lines(n, flag, observed_count) AS (
            SELECT 1, (SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname = current_user), NULL::bigint
  UNION ALL SELECT 2, NULL, (SELECT count(*) FROM repo)
  UNION ALL SELECT 3, NULL, (SELECT count(*) FROM led)
  UNION ALL SELECT 4, NULL, (SELECT count(*) FROM led WHERE NOT ok)
  UNION ALL SELECT 5, NULL, (SELECT count(*) FROM led l WHERE NOT EXISTS (SELECT 1 FROM repo r WHERE r.name = l.name))
  UNION ALL SELECT 6, NULL, (SELECT count(*) FROM notrun)
  UNION ALL SELECT 7, (SELECT done FROM leads), NULL
  UNION ALL SELECT 8, NOT EXISTS (SELECT 1 FROM led WHERE name = '20261108090000_lead_claimed_phone'), NULL
  UNION ALL SELECT 9, NOT EXISTS (SELECT 1 FROM led WHERE name = '20261109090000_accountant_delivery_permission'), NULL
  UNION ALL SELECT 10, NOT EXISTS (SELECT 1 FROM led WHERE name = '20261109091000_accountant_link_otp'), NULL
  UNION ALL SELECT 11, NOT EXISTS (SELECT 1 FROM notrun WHERE name NOT IN (SELECT name FROM expect))
                       AND NOT EXISTS (SELECT 1 FROM expect e WHERE e.name NOT IN (SELECT name FROM notrun)), NULL
  UNION ALL SELECT 12, NOT EXISTS (SELECT 1 FROM repo r WHERE r.name NOT IN (SELECT name FROM expect)
                                     AND NOT EXISTS (SELECT 1 FROM led l WHERE l.name = r.name AND l.ok)), NULL
  UNION ALL SELECT 13, NULL, (SELECT count(*) FROM led l JOIN repo r ON r.name = l.name WHERE l.ok AND l.checksum <> r.lf)
  UNION ALL SELECT 14, NULL, (SELECT count(*) FROM led l JOIN repo r ON r.name = l.name WHERE l.ok AND l.checksum NOT IN (r.lf, r.crlf))
)
SELECT n, flag, observed_count FROM lines ORDER BY n;

